pub struct PredictedOccupancyStruct {
    pub start_timestamp: types::EpochS,
    pub end_timestamp: types::EpochS,
    pub occupancy: globals::OccupancyBitmap,
    pub confidence: types::Percent,
}

impl PredictedOccupancyStruct {
    pub const FIELD_CONFIDENCE: FieldId = FieldId::new(0x3);
    pub const FIELD_END_TIMESTAMP: FieldId = FieldId::new(0x1);
    pub const FIELD_OCCUPANCY: FieldId = FieldId::new(0x2);
    pub const FIELD_START_TIMESTAMP: FieldId = FieldId::new(0x0);

    #[must_use]
    pub fn new(
        start_timestamp: impl Into<types::EpochS>,
        end_timestamp: impl Into<types::EpochS>,
        occupancy: impl Into<globals::OccupancyBitmap>,
        confidence: impl Into<types::Percent>,
    ) -> Self {
        Self {
            start_timestamp: start_timestamp.into(),
            end_timestamp: end_timestamp.into(),
            occupancy: occupancy.into(),
            confidence: confidence.into(),
        }
    }

    pub(crate) fn decode_fields_inner(
        fields: Vec<(FieldId, AttributeValue)>,
    ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
        let mut start_timestamp = None;
        let mut end_timestamp = None;
        let mut occupancy = None;
        let mut confidence = None;
        for (fid, fval) in fields {
            match fid.raw() {
                0 => {
                    if start_timestamp.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <types::EpochS>::try_from(fval)?;
                        start_timestamp = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                1 => {
                    if end_timestamp.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <types::EpochS>::try_from(fval)?;
                        (decoded.raw() >= 1_u32)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        end_timestamp = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                2 => {
                    if occupancy.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <globals::OccupancyBitmap>::try_from(fval)?;
                        occupancy = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                3 => {
                    if confidence.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <types::Percent>::try_from(fval)?;
                        (decoded.raw() <= 100_u8)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        confidence = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                _ => return Err((Some(fid), MatterStatus::ConstraintError)),
            }
        }
        Ok(Self {
            start_timestamp: start_timestamp.ok_or((Some(FieldId::new(0)), MatterStatus::ConstraintError))?,
            end_timestamp: end_timestamp.ok_or((Some(FieldId::new(1)), MatterStatus::ConstraintError))?,
            occupancy: occupancy.ok_or((Some(FieldId::new(2)), MatterStatus::ConstraintError))?,
            confidence: confidence.ok_or((Some(FieldId::new(3)), MatterStatus::ConstraintError))?,
        })
    }

    pub(crate) fn encode_fields_inner(self) -> Vec<(FieldId, AttributeValue)> {
        alloc::vec![
            (Self::FIELD_START_TIMESTAMP, AttributeValue::from(self.start_timestamp)),
            (Self::FIELD_END_TIMESTAMP, AttributeValue::from(self.end_timestamp)),
            (Self::FIELD_OCCUPANCY, AttributeValue::from(self.occupancy)),
            (Self::FIELD_CONFIDENCE, AttributeValue::from(self.confidence)),
        ]
    }
}

